CREATE MATERIALIZED VIEW mv_daily_sales AS
SELECT
    date_trunc('day', ordered_at) AS sales_day,
    sum(amount)                  AS revenue
FROM orders
GROUP BY 1;

CREATE UNIQUE INDEX ux_mv_daily_sales_day
ON mv_daily_sales (sales_day);

\timing on
REFRESH MATERIALIZED VIEW CONCURRENTLY mv_daily_sales;
\timing off

-- Check when the data was last built (store it yourself)
SELECT max(sales_day) FROM mv_daily_sales;
